import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { applyEditPatch, type EditPatch } from "../../packages/engine-client/src/patch";
import { parseEditOutcome } from "../../packages/engine-client/src/editing";
import type { Clip, Project, Track } from "../../packages/engine-client/src/model.generated";
import { projectToJson } from "../../apps/web/src/preview/projectJson";

interface Case { name: string; before: Project; patch: EditPatch; after: Project }
// Real edits made by the engine (generated by `cargo test -p app-timeline patch_contract`): the patch applied to `before` must give `after`.
const contract = JSON.parse(readFileSync(new URL("../../packages/engine-client/schema/patch-contract.json", import.meta.url), "utf8")) as { cases: Case[] };

test("every patch the engine made reproduces the project it came from (contract with crates/timeline)", () => {
  assert.ok(contract.cases.length >= 10);
  for (const c of contract.cases) {
    const before = structuredClone(c.before);
    const got = applyEditPatch(c.before, c.patch);
    assert.deepEqual(got, c.after, c.name);
    assert.deepEqual(c.before, before, `${c.name}: the input project was mutated`);
  }
});

test("a patch keeps every track and clip it does not name (same objects), so memoised views can skip them", () => {
  const split = contract.cases.find((c) => c.name === "split the first clip")!;
  const got = applyEditPatch(split.before, split.patch);
  const [b, a] = [split.before.sequences[0]!.tracks, got.sequences[0]!.tracks];
  assert.notEqual(a[0], b[0], "the edited track is new");
  b.slice(1).forEach((t, i) => assert.equal(a[i + 1], t, "an untouched track is the same object"));
  assert.equal(a[0]!.clips[2], b[0]!.clips[1], "a clip after the splice is the same object");
  assert.equal(got.media, split.before.media);
});

test("a patch that changes nothing returns the same project object", () => {
  const p = contract.cases[0]!.before;
  assert.equal(applyEditPatch(p, { sequences: [] }), p);
  assert.equal(applyEditPatch(p, { sequences: [{ id: p.sequences[0]!.id, tracks: [] }] }), p);
});

test("a patch that does not fit throws, so the store can re-read the project", () => {
  const p = contract.cases[0]!.before;
  const seq = p.sequences[0]!;
  assert.throws(() => applyEditPatch(p, { sequences: [{ id: "nope", tracks: [] }] }), /unknown sequence/);
  assert.throws(() => applyEditPatch(p, { sequences: [{ id: seq.id, tracks: [{ id: seq.tracks[0]!.id, splice: { start: 5, remove: 9, insert: [] } }] }] }), /out of range/);
  assert.throws(() => applyEditPatch(p, { sequences: [{ id: seq.id, tracks: [{ id: "new" }] }] }), /without its shell/);
  assert.throws(() => applyEditPatch(p, { sequences: [{ id: seq.id, order: ["ghost"], tracks: [] }] }), /unknown track/);
});

test("the outcome parser keeps the patch and ignores a malformed one", () => {
  const base = { revision: 1, can_undo: true, can_redo: false, changed: true };
  const patch = { sequences: [] };
  assert.deepEqual(parseEditOutcome(JSON.stringify({ ...base, patch })).patch, patch);
  assert.equal(parseEditOutcome(JSON.stringify(base)).patch, undefined);
  assert.equal(parseEditOutcome(JSON.stringify({ ...base, patch: 3 })).patch, undefined);
});

// ---- Property-style: random edits, patch made by a reference diff, applied == the new project (a seeded generator keeps failures replayable) ----

function rng(seed: number) {
  let s = seed >>> 0;
  return () => ((s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 2 ** 32);
}
const clip = (id: string, start: number): Clip => ({ id, media: "m", start, source_in: 0, duration: 10, speed: { num: 1, den: 1 } } as unknown as Clip);
const track = (id: string, n: number): Track => ({ id, kind: "video", name: id, muted: false, locked: false, clips: Array.from({ length: n }, (_, i) => clip(`${id}c${i}`, i * 20)) });
const mk = (tracks: Track[]): Project => ({ schema_version: 5, id: "p", name: "P", media: [], sequences: [{ id: "s", name: "S", frame_rate: { num: 30, den: 1 }, resolution: { width: 1, height: 1 }, sample_rate: 48000, tracks }] }) as unknown as Project;

const strip = (t: Track): Omit<Track, "clips"> => { const c: Partial<Track> = { ...t }; delete c.clips; return c as Omit<Track, "clips">; };

/** The same prefix/suffix splice the engine makes, written independently. */
function referenceDiff(a: Project, b: Project): EditPatch {
  const sa = a.sequences[0]!, sb = b.sequences[0]!;
  const same = sa.tracks.length === sb.tracks.length && sa.tracks.every((t, i) => t.id === sb.tracks[i]!.id);
  const tracks = sb.tracks.flatMap((t) => {
    const old = sa.tracks.find((x) => x.id === t.id);
    const shell = strip(t);
    if (!old) return [{ id: t.id, shell: { ...shell, clips: [] }, splice: { start: 0, remove: 0, insert: t.clips } }];
    const oshell = strip(old);
    const shellChanged = JSON.stringify(oshell) !== JSON.stringify(shell);
    let p = 0;
    while (p < old.clips.length && p < t.clips.length && JSON.stringify(old.clips[p]) === JSON.stringify(t.clips[p])) p++;
    let s = 0;
    while (s < old.clips.length - p && s < t.clips.length - p && JSON.stringify(old.clips[old.clips.length - 1 - s]) === JSON.stringify(t.clips[t.clips.length - 1 - s])) s++;
    const changed = p !== old.clips.length || p !== t.clips.length;
    if (!shellChanged && !changed) return [];
    return [{ id: t.id, ...(shellChanged ? { shell: { ...shell, clips: [] } as Track } : {}), ...(changed ? { splice: { start: p, remove: old.clips.length - p - s, insert: t.clips.slice(p, t.clips.length - s) } } : {}) }];
  });
  return { sequences: [{ id: sb.id, ...(same ? {} : { order: sb.tracks.map((t) => t.id) }), tracks }] };
}

test("random edit sequences: the patched project equals the new project, and untouched tracks are shared", () => {
  for (let seed = 1; seed <= 200; seed++) {
    const r = rng(seed);
    let cur = mk([track("a", 6), track("b", 3), track("c", 0)]);
    let nextId = 100;
    for (let step = 0; step < 25; step++) {
      const next: Project = structuredClone(cur);
      const tracks = next.sequences[0]!.tracks;
      const t = tracks[Math.floor(r() * tracks.length)]!;
      const k = r();
      if (k < 0.3 && t.clips.length) t.clips.splice(Math.floor(r() * t.clips.length), 1);
      else if (k < 0.55) t.clips.splice(Math.floor(r() * (t.clips.length + 1)), 0, clip(`n${nextId++}`, nextId));
      else if (k < 0.7 && t.clips.length) { const i = Math.floor(r() * t.clips.length); t.clips[i] = { ...t.clips[i]!, duration: t.clips[i]!.duration + 1 }; }
      else if (k < 0.8) t.muted = !t.muted;
      else if (k < 0.88) tracks.splice(Math.floor(r() * (tracks.length + 1)), 0, track(`t${nextId++}`, Math.floor(r() * 3)));
      else if (k < 0.94 && tracks.length > 1) tracks.splice(Math.floor(r() * tracks.length), 1);
      else tracks.reverse();
      const patch = referenceDiff(cur, next);
      const frozen = structuredClone(cur);
      const got = applyEditPatch(cur, patch);
      assert.deepEqual(got, next, `seed ${seed} step ${step}`);
      assert.deepEqual(cur, frozen, "input untouched");
      const named = new Set(patch.sequences[0]?.tracks.map((x) => x.id));
      for (const t0 of cur.sequences[0]!.tracks) {
        const t1 = got.sequences[0]!.tracks.find((x) => x.id === t0.id);
        if (t1 && !named.has(t0.id)) assert.equal(t1, t0, `seed ${seed} step ${step}: untouched track not shared`);
      }
      // The preview's cached JSON of the patched project is the same document as a plain stringify.
      assert.deepEqual(JSON.parse(projectToJson(got)), JSON.parse(JSON.stringify(got)));
      cur = got;
    }
  }
});
